<script setup lang="ts">
import { computed, inject, onMounted, ref } from "vue";
import { Activity, ArrowClockwise, ArrowUpRight, Bell, CheckCircle, Cpu, Database, Gauge, HardDrives, Pulse, Warning } from "@phosphor-icons/vue";
import type { APIClient } from "../api";
import { router } from "../router";
import { sessionStore } from "../store";

interface MetricProjection { name?:string;label?:string;value?:number;unit?:string;available?:boolean;complete?:boolean;missing_reason?:string;observed_at?:string;sample_interval?:number }
interface UsageProjection { dimension?:string;used?:number;limit?:number;unit?:string;available?:boolean;limit_state?:string;missing_reason?:string;updated_at?:string }
const api=inject<APIClient>("api")!;const loading=ref(true);const error=ref("");const raw=ref<Record<string,unknown>>({});
const node=computed(()=>record(raw.value.node));
const metrics=computed(()=>{
  const generatedAt=String(raw.value.generated_at||"");
  const counts=Object.entries(record(raw.value.counts)).flatMap(([name,value])=>Number.isFinite(Number(value))?[{name:`count.${name}`,label:humanize(name),value:Number(value),unit:"count",available:true,complete:true,observed_at:generatedAt}]:[]);
  return [...counts,...list(raw.value.metrics)] as unknown as MetricProjection[];
});
const usage=computed(()=>list(raw.value.usage) as unknown as UsageProjection[]);
const services=computed(()=>list(raw.value.services));
const alerts=computed(()=>list(raw.value.alerts));
const warnings=computed(()=>Array.isArray(raw.value.warnings)?raw.value.warnings.map((item)=>String(item)):[]);
onMounted(()=>void load());
async function load():Promise<void>{
  loading.value=true;error.value="";
  const operations=["dashboard.summary","observability.dashboard.get"].filter((operation)=>api.available(operation));
  if(!operations.length){raw.value={};error.value="No dashboard projection is enabled on this node.";loading.value=false;return}
  const responses=await Promise.allSettled(operations.map(async(operation)=>({operation,result:(await api.invoke<unknown>(operation,{tenantId:sessionStore.state.tenantId||undefined,payload:{}})).result})));
  const fulfilled=responses.flatMap((response)=>response.status==="fulfilled"?[response.value]:[]);
  if(!fulfilled.length){const rejected=responses.find((response)=>response.status==="rejected");raw.value={};error.value=rejected&&rejected.status==="rejected"&&rejected.reason instanceof Error?rejected.reason.message:"Dashboard projection failed.";loading.value=false;return}
  const summary=record(fulfilled.find((entry)=>entry.operation==="dashboard.summary")?.result);
  const observability=record(fulfilled.find((entry)=>entry.operation==="observability.dashboard.get")?.result);
  raw.value={...summary,...observability,node:{...record(summary.node),...record(observability.node)},counts:record(summary.counts),warnings:[...strings(summary.warnings),...strings(observability.warnings)]};
  loading.value=false;
}
function list(value:unknown):Record<string,unknown>[]{return Array.isArray(value)?value.filter(isRecord):[]}function record(value:unknown):Record<string,unknown>{return isRecord(value)?value:{}}function isRecord(value:unknown):value is Record<string,unknown>{return Boolean(value)&&typeof value==="object"&&!Array.isArray(value)}
function strings(value:unknown):string[]{return Array.isArray(value)?value.map(String):[]}
function text(value:unknown,fallback="—"):string{return value===undefined||value===null||value===""?fallback:String(value)}
function metricValue(metric:MetricProjection):string{if(!metric.available||!Number.isFinite(metric.value))return"—";const value=Number(metric.value);if(metric.unit==="percent")return`${value.toFixed(value>=10?0:1)}%`;if(metric.unit==="ratio")return`${(value*100).toFixed(value>=.1?0:1)}%`;if(metric.unit==="bytes")return formatBytes(value);if(metric.unit==="bytes_per_second")return`${formatBytes(value)}/s`;return new Intl.NumberFormat(undefined,{maximumFractionDigits:2}).format(value)}
function metricDetail(metric:MetricProjection):string{if(!metric.available)return humanize(metric.missing_reason||"missing data");const coverage=metric.complete?"complete interval":"partial interval";return`${coverage} · ${date(metric.observed_at)}`}
function metricTone(metric:MetricProjection):string{if(!metric.available)return"neutral";const value=Number(metric.value);if(metric.unit==="percent"&&value>=90||metric.unit==="ratio"&&value>=.9)return"critical";if(metric.unit==="percent"&&value>=75||metric.unit==="ratio"&&value>=.75||!metric.complete)return"warning";return"healthy"}
function usageValue(item:UsageProjection,key:"used"|"limit"):string{if(!item.available&&key==="used")return"—";const value=Number(item[key]);if(!Number.isFinite(value))return"—";return item.unit==="bytes"?formatBytes(value):new Intl.NumberFormat().format(value)}
function formatBytes(value:number):string{if(!Number.isFinite(value)||value<0)return"—";const units=["B","KiB","MiB","GiB","TiB","PiB"];let amount=value,index=0;while(amount>=1024&&index<units.length-1){amount/=1024;index++}return`${amount>=10||index===0?amount.toFixed(0):amount.toFixed(1)} ${units[index]}`}
function date(value:unknown):string{if(!value)return"not observed";const parsed=new Date(String(value));return Number.isNaN(parsed.valueOf())?"not observed":new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short"}).format(parsed)}
function humanize(value:unknown):string{return text(value,"unknown").replaceAll("_"," ")}
function route(path:string):void{router.push(path)}
const iconFor=(index:number)=>[Cpu,Gauge,Database,HardDrives,Activity,Pulse][index]||Activity;
</script>

<template>
  <main class="dashboard">
    <header class="dashboard-head">
      <div><p class="eyebrow">NODE / CACHED OBSERVATION</p><h2>Operational overview</h2><p>Historical telemetry, tenant limits, alerts, and functional service evidence without a fresh host scan.</p></div>
      <div class="head-actions"><span class="node-state" :class="`status-${text(node.health,'unknown').toLowerCase()}`">{{text(node.hostname,'Local node')}} · {{humanize(node.health)}}</span><button class="button button-small" type="button" :disabled="loading" @click="load"><ArrowClockwise :size="15" :class="{spinning:loading}"/>Refresh</button></div>
    </header>
    <div v-if="error" class="dashboard-error"><Warning :size="18"/>{{error}}</div>
    <section class="metrics" :aria-busy="loading">
      <article v-for="(metric,index) in metrics" :key="metric.name||metric.label" class="metric">
        <div class="metric-icon" :class="`tone-${metricTone(metric)}`"><component :is="iconFor(index)" :size="18"/></div>
        <div><p>{{text(metric.label,'Metric')}}</p><strong>{{loading?'—':metricValue(metric)}}</strong><span>{{loading?'Loading cached projection':metricDetail(metric)}}</span></div>
      </article>
      <article v-if="!loading&&!metrics.length" class="metric metric-missing"><Activity :size="20"/><div><p>Telemetry</p><strong>—</strong><span>No metric series has been published.</span></div></article>
    </section>
    <div class="dashboard-grid">
      <section class="panel usage-panel"><header><div><p>TENANT PROJECTION</p><h3>Usage & limits</h3></div><button type="button" @click="route('/observability')">Evidence<ArrowUpRight :size="14"/></button></header><div v-if="loading" class="panel-loading"><span v-for="i in 5" :key="i" class="skeleton"></span></div><div v-else-if="!usage.length" class="inline-empty"><Database :size="25"/><div><strong>Usage unavailable</strong><span>The materialized usage collector has not published this tenant.</span></div></div><div v-else class="usage-list"><article v-for="item in usage.slice(0,8)" :key="item.dimension"><div><strong>{{humanize(item.dimension)}}</strong><small>{{item.available?date(item.updated_at):humanize(item.missing_reason)}}</small></div><div><b>{{usageValue(item,'used')}}</b><span>/ {{usageValue(item,'limit')}}</span><i :class="`status-${text(item.limit_state,'unknown')}`">{{humanize(item.limit_state)}}</i></div></article></div></section>
      <section class="panel alert-panel"><header><div><p>ALERT DELIVERY</p><h3>Inbox</h3></div><button type="button" @click="route('/alerts')">Open inbox<ArrowUpRight :size="14"/></button></header><div v-if="loading" class="panel-loading"><span v-for="i in 4" :key="i" class="skeleton"></span></div><div v-else-if="!alerts.length" class="inline-empty"><CheckCircle :size="25"/><div><strong>No delivered alerts</strong><span>No tenant notification currently requires attention.</span></div></div><div v-else class="alert-list"><article v-for="item in alerts.slice(0,6)" :key="text(item.id)"><Bell :size="16"/><div><strong>{{text(item.subject)}}</strong><small>{{humanize(item.kind)}} · {{date(item.updated_at)}}</small></div><span :class="`severity-${text(item.severity,'info').toLowerCase()}`">{{text(item.severity,'info')}}</span></article></div></section>
      <section class="panel service-panel"><header><div><p>FUNCTIONAL HEALTH</p><h3>Managed services</h3></div><button type="button" @click="route('/services')">All services<ArrowUpRight :size="14"/></button></header><div class="service-grid"><article v-for="item in services.slice(0,8)" :key="text(item.id)"><span class="status" :class="`status-${text(item.health,'unknown').toLowerCase()}`">{{text(item.name)}}</span><small>{{item.missing_reason?humanize(item.missing_reason):`${humanize(item.active)} · ${item.externally_functional?'externally functional':'external function unproven'}`}}</small></article><div v-if="!loading&&!services.length" class="inline-empty compact"><Pulse :size="22"/><span>No cached service observation is available.</span></div></div></section>
      <section class="panel quality-panel"><header><div><p>DATA QUALITY</p><h3>Projection notices</h3></div><span>{{date(raw.generated_at)}}</span></header><ol><li v-for="warning in warnings" :key="warning"><Warning :size="14"/><span>{{warning}}</span></li><li v-if="!loading&&!warnings.length"><CheckCircle :size="14"/><span>No missing-data notice was reported.</span></li></ol></section>
    </div>
  </main>
</template>

<style scoped>
.dashboard{padding:34px clamp(18px,3.2vw,48px) 64px;max-width:1700px;margin:0 auto}.dashboard-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:27px}.dashboard-head h2{margin:5px 0 8px;font-size:clamp(29px,3vw,39px);letter-spacing:-.045em;line-height:1}.dashboard-head>div>p:last-child{margin:0;color:var(--muted)}.eyebrow{color:var(--accent);font:10px/1 "Panel Mono",monospace;letter-spacing:.13em;margin:0}.head-actions{display:flex;align-items:center;gap:12px}.node-state{font:10px/1 "Panel Mono",monospace;text-transform:uppercase}.dashboard-error{display:flex;align-items:center;gap:8px;margin:0 0 15px;padding:11px 13px;border-left:3px solid var(--critical);background:color-mix(in srgb,var(--critical),transparent 92%);color:var(--critical)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));border:1px solid var(--border);background:var(--border);gap:1px;margin-bottom:18px}.metric{min-height:126px;background:var(--surface);padding:16px;display:flex;gap:13px}.metric-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:7px;background:var(--surface-2);color:var(--subtle);flex:0 0 auto}.tone-healthy{color:var(--healthy);background:color-mix(in srgb,var(--healthy),transparent 91%)}.tone-warning{color:var(--warning);background:color-mix(in srgb,var(--warning),transparent 91%)}.tone-critical{color:var(--critical);background:color-mix(in srgb,var(--critical),transparent 91%)}.metric p{margin:1px 0 8px;color:var(--muted);font-size:11px}.metric strong{display:block;font:23px/1 "Panel Mono",monospace;letter-spacing:-.04em}.metric span{display:block;margin-top:9px;color:var(--subtle);font-size:10px}.metric-missing{grid-column:1/-1}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr);gap:18px}.panel{border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);min-width:0}.panel>header{min-height:68px;padding:14px 17px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}.panel header p{margin:0 0 6px;color:var(--subtle);font:9px/1 "Panel Mono",monospace;letter-spacing:.12em}.panel header h3{margin:0;font-size:15px}.panel header button{border:0;background:transparent;color:var(--accent);display:flex;align-items:center;gap:6px;cursor:pointer;font-size:11px}.panel>header>span{color:var(--subtle);font-size:9px}.usage-list article{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 16px;border-bottom:1px solid var(--border)}.usage-list article:last-child{border:0}.usage-list article>div{display:grid;gap:4px}.usage-list article>div:last-child{grid-template-columns:auto auto auto;align-items:center}.usage-list strong{font-size:12px;text-transform:capitalize}.usage-list small,.usage-list span{color:var(--subtle);font-size:9px}.usage-list b{font:12px/1 "Panel Mono",monospace}.usage-list i{font:9px/1 "Panel Mono",monospace;font-style:normal;text-transform:uppercase;margin-left:8px}.alert-list article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;padding:13px 16px;border-bottom:1px solid var(--border)}.alert-list article:last-child{border:0}.alert-list div{display:grid;gap:5px}.alert-list strong{font-size:12px}.alert-list small{color:var(--subtle);font-size:9px}.alert-list>article>span{font:9px/1 "Panel Mono",monospace;text-transform:uppercase}.severity-critical,.severity-error{color:var(--critical)}.severity-warning{color:var(--warning)}.service-grid{display:grid;grid-template-columns:repeat(2,1fr)}.service-grid article{min-height:63px;padding:13px 16px;border-bottom:1px solid var(--border);display:grid;gap:7px}.service-grid article:nth-child(odd){border-right:1px solid var(--border)}.service-grid small{color:var(--subtle);overflow:hidden;text-overflow:ellipsis}.quality-panel ol{list-style:none;margin:0;padding:8px 16px 14px}.quality-panel li{display:flex;gap:9px;padding:9px 0;color:var(--muted);font-size:10px}.quality-panel li svg{color:var(--warning);flex:0 0 auto}.inline-empty{min-height:130px;display:flex;justify-content:center;align-items:center;gap:11px;color:var(--subtle);padding:25px}.inline-empty div{display:grid;gap:5px}.inline-empty span{color:var(--subtle);font-size:11px}.inline-empty.compact{grid-column:1/-1;min-height:110px}.panel-loading{display:grid;gap:8px;padding:15px}.panel-loading .skeleton{height:36px}.spinning{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(1turn)}}
@media(max-width:1250px){.metrics{grid-template-columns:repeat(3,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:700px){.dashboard{padding:23px 14px 50px}.dashboard-head{align-items:flex-start;flex-direction:column}.head-actions{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr)}.metric{min-height:112px;padding:13px}.usage-list article>div:last-child{grid-template-columns:auto auto}.usage-list i{grid-column:1/-1;margin-left:0}}
</style>
